// Simple Asteroid Escape game targeting <canvas id="game"></canvas>
(function(){
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 600;

  // Ship
  const ship = {w:40, h:20, x:W/2, y:H-30, speed:6};
  const keys = {left:false, right:false};

  // Asteroids
  const asteroids = [];
  let asteroidTimer = 0;
  const asteroidInterval = 90; // frames
  let level = 0;
  let score = 0;
  let startTime = null;
  let gameOver = false;

  function spawnAsteroid(){
    const size = 20 + Math.random()*30;
    asteroids.push({x:Math.random()*(W-size), y:-size, w:size, h:size, speed:2+level*0.3});
  }

  function update(){
    if (gameOver) return;
    // ship movement
    if (keys.left) ship.x -= ship.speed;
    if (keys.right) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(W-ship.w, ship.x));

    // asteroids
    asteroidTimer++;
    if (asteroidTimer >= asteroidInterval){
      asteroidTimer = 0;
      spawnAsteroid();
    }
    asteroids.forEach(a=>a.y+=a.speed);
    // remove off‑screen
    for(let i=asteroids.length-1;i>=0;i--){
      if (asteroids[i].y>H) asteroids.splice(i,1);
    }
    // collision
    for(const a of asteroids){
      if (a.x < ship.x+ship.w && a.x+a.w > ship.x && a.y < ship.y+ship.h && a.y+a.h > ship.y){
        gameOver = true;
        break;
      }
    }
    // score & difficulty
    const elapsed = (Date.now()-startTime)/1000;
    score = Math.floor(elapsed);
    level = Math.floor(elapsed/10);
  }

  function draw(){
    ctx.clearRect(0,0,W,H);
    // ship
    ctx.fillStyle = '#0af';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // asteroids
    ctx.fillStyle = '#a44';
    asteroids.forEach(a=>ctx.fillRect(a.x,a.y,a.w,a.h));
    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: '+score, 10, 20);
    if (gameOver){
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', W/2-60, H/2);
    }
  }

  function loop(){
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // input
  document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')keys.left=true; if(e.key==='ArrowRight')keys.right=true;});
  document.addEventListener('keyup',e=>{if(e.key==='ArrowLeft')keys.left=false; if(e.key==='ArrowRight')keys.right=false;});
  canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect(); ship.x = e.clientX - rect.left - ship.w/2;});

  // start
  startTime = Date.now();
  requestAnimationFrame(loop);
})();
